				<view class="info-rows">
					<view class="info-row">
						<view class="left">{{detail.true_money_title}}</view>
						<view class="right">{{detail.true_money_tv}}</view>
					</view>
					<view class="info-row">
						<view class="left">{{detail.taxfee_title}}</view>
						<view class="right">{{detail.taxfee_tv}}</view>
					</view>
					<view class="info-row">
						<view class="left">{{detail.order_sn_title}}</view>
						<view class="right">{{detail.order_sn}}</view>
