		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				id:0,
			}
		},
		onLoad(e) {
			_this = this;
			if(e.id){
				_this.id = e.id
			}else{
				this.$u.toast('提交参数有误')
				setTimeout(()=>{
					_this.finish()
				},2000)
				return
			}
			_this.get_tixian_xq()
		},
		methods: {
			async get_tixian_xq(){
				const params = {
					id: _this.id,
				}
				const data = await _this.$post('port/tixian_xq', params)
				if(data.code==1){
					_this.detail = data.result
					if (_this.load) {
						_this.load = false
					}
				}else{
					this.$u.toast(data.msg)
				}
			}
		}
	}
</script>

